const language=localStorage.getItem('zarin_language')||'fa';
i18n.use(initReactI18next).init({resources:{fa,ps,en},lng:language,fallbackLng:'fa',interpolation:{escapeValue:false}});
const applyDirection = (lng) => {
  document.documentElement.lang = lng;
  document.documentElement.dir = lng === 'en' ? 'ltr' : 'rtl';
  document.documentElement.setAttribute('data-lang', lng);
  document.body?.setAttribute('dir', lng === 'en' ? 'ltr' : 'rtl');
  document.body?.setAttribute('data-lang', lng);
};
applyDirection(language);
i18n.on('languageChanged',(lng)=>{localStorage.setItem('zarin_language',lng);applyDirection(lng);});
export default i18n;

